package com.example.study_planner

import android.content.Intent
import android.provider.Settings
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

/**
 * Replaces the MainActivity generated by `flutter create` (CI copies this file over it).
 * Exposes the "attention" channel used by lib/attention.dart.
 */
class MainActivity : FlutterActivity() {
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "attention")
            .setMethodCallHandler { call, result ->
                try {
                    when (call.method) {
                        "hasAccess" -> result.success(AttentionCore.hasAccess(this))
                        "openAccessSettings" -> {
                            val i = Intent(Settings.ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS)
                            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                            startActivity(i)
                            result.success(true)
                        }
                        "status" -> result.success(AttentionCore.status(this))
                        "enable" -> {
                            val by = call.argument<String>("by") ?: "manual"
                            val endAt = (call.argument<Number>("endAt") ?: 0).toLong()
                            result.success(AttentionCore.enable(this, by, endAt))
                        }
                        "disable" -> {
                            val by = call.argument<String>("by") ?: "manual"
                            result.success(AttentionCore.disable(this, by))
                        }
                        else -> result.notImplemented()
                    }
                } catch (e: Exception) {
                    result.error("attention", e.toString(), null)
                }
            }
    }
}
